package project;

/** Full board list with board links, client-side paging, and a keyword search bar. */
final class BoardListPage {
    private BoardListPage() {}

    static String render() {
        return "<!doctype html><html lang='ko'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>게시판 | CINEHUB</title>"
            + "<link rel='stylesheet' href='/static/assets/css/style.css'><script src='/static/assets/js/site-header.js' defer></script><script src='/static/assets/js/pagination.js'></script><link rel='stylesheet' href='/static/assets/css/widgets.css'><link rel='stylesheet' href='/static/assets/css/responsive.css'><link rel='stylesheet' href='/static/assets/css/post-layout.css'></head><body class='logged-in'>"
            + ""+CinehubServer.siteHeader()+""
            + "<main><div class='container'><section class='hero board-panel'><div class='widget-header-3'><h1 class='widget-title'>게시판</h1></div><nav class='board-links' id='boardLinks'><a class='active' href='/posts'>전체</a></nav><div class='list-search'><input id='postSearch' placeholder='제목, 내용, 작성자 검색'><button id='postSearchButton'>검색</button></div><nav class='pagination pagination-top' id='postPaginationTop'></nav><div id='posts'><p class='muted'>게시글을 불러오는 중입니다.</p></div><nav class='pagination' id='postPagination'></nav></section></div></main><footer class='main-footer'><div class='container'><p class='text-center text-muted'>CINEHUB · 영화 탐색 커뮤니티</p></div></footer>"
            + "<script>function safe(v){var d=document.createElement('div');d.textContent=v||'';return d.innerHTML;}var allPosts=[],page=1;function filtered(){var q=document.getElementById('postSearch').value.trim().toLowerCase();return q?allPosts.filter(function(p){return (p.title+' '+p.content+' '+p.author).toLowerCase().indexOf(q)>=0;}):allPosts;}function draw(){var a=filtered(),pages=Math.max(1,Math.ceil(a.length/10));if(page>pages)page=1;document.getElementById('posts').innerHTML=a.slice((page-1)*10,page*10).map(function(p){return '<a class=\"post-card\" href=\"/post/'+p.id+'\"><h3>'+safe(p.title)+'</h3><p>'+safe(p.content).slice(0,100)+'</p><small>'+safe(p.author)+' · '+safe(p.createdAt)+'</small></a>';}).join('')||'<p class=\"muted\">검색 결과가 없습니다.</p>';['postPaginationTop','postPagination'].forEach(function(navId){renderPagination(document.getElementById(navId),page,pages,function(n){page=n;draw();window.scrollTo({top:0,behavior:'smooth'});});});}function doSearch(){page=1;draw();}document.getElementById('postSearchButton').onclick=doSearch;document.getElementById('postSearch').onkeydown=function(e){if(e.key==='Enter')doSearch();};fetch('/api/boards').then(function(r){return r.json();}).then(function(d){document.getElementById('boardLinks').innerHTML='<a class=\"active\" href=\"/posts\">전체</a>'+(d.boards||[]).map(function(b){return '<a href=\"/category/'+b.id+'\">'+safe(b.name)+'</a>';}).join('');});fetch('/api/posts').then(function(r){return r.json();}).then(function(d){allPosts=d.posts||[];draw();});fetch('/api/me').then(function(r){return r.ok?r.json():null;}).then(function(u){if(!u)return;document.getElementById('navLogin').style.display='none';document.getElementById('navRegister').style.display='none';document.getElementById('navUser').style.display='inline-block';document.getElementById('navLogout').style.display='inline-block';document.getElementById('navMyPage').textContent=u.nickname+'님';document.getElementById('navNotifications').style.display='list-item';if(u.role==='ADMIN')document.getElementById('navAdmin').style.display='list-item';});document.getElementById('navLogout').onclick=function(e){e.preventDefault();fetch('/api/auth/logout',{method:'POST'}).then(function(){location.href='/';});};</script></body></html>";
    }
}
